def can_see_white_sheet(x1, y1, x2, y2, x3, y3, x4, y4, x5, y5, x6, y6):
    def is_inside(x, y, x1, y1, x2, y2):
        return x1 <= x <= x2 and y1 <= y <= y2

    def is_outside(x, y, x1, y1, x2, y2):
        return x < x1 or x > x2 or y < y1 or y > y2

    def is_visible_from_edge(x1, y1, x2, y2, x3, y3, x4, y4, x5, y5, x6, y6):
        # Check if any point on the edge of the white sheet is visible
        for dx in range(-1, 2):
            for dy in range(-1, 2):
                if dx == 0 and dy == 0:
                    continue
                px = x1 + dx * (x2 - x1)
                py = y1 + dy * (y2 - y1)
                if is_outside(px, py, x3, y3, x4, y4) and is_outside(px, py, x5, y5, x6, y6):
                    return True
        return False

    return is_visible_from_edge(x1, y1, x2, y2, x3, y3, x4, y4, x5, y5, x6, y6)

